class Ball {
    constructor(diameter, color, drawnstyle='hachure', start_x, start_y, despawned=false, canvas){
        this.diameter = diameter;
        this.color = color;
        this.drawnstyle = drawnstyle;
        this.start_x = start_x;
        this.start_y = start_y;
        this.despawned = despawned;
